blocks.value:
.seccion {
    width: min(100% - 2rem, 1120px);
    margin-inline: auto;
}

.hero h1 {
    font-size: clamp(2.2rem, 7vw, 5rem);
}

img {
    display: block;
    max-width: 100%;
}

.ruta img {
    width: 100%;
    height: 220px;
    object-fit: cover;
}

/* Base: pantalla estrecha */
.encabezado { padding: 1rem; }
.menu { display: flex; flex-wrap: wrap; gap: 0.75rem; }
.recomendaciones { display: grid; gap: 1.5rem; }

@media (min-width: 700px) {
    .recomendaciones {
        grid-template-columns: 1fr 1fr;
        align-items: center;
    }
}

@media (min-width: 1000px) {
    .ruta--principal {
        grid-column: span 2;
    }
}

.boton:hover {
    background-color: #0a6048;
}
.boton:focus-visible {
    outline: 3px solid #f7b32b;
    outline-offset: 4px;
}
.boton:active {
    transform: translateY(1px);
}

.nivel::before {
    content: "";
    display: inline-block;
    width: 0.6rem;
    height: 0.6rem;
    margin-right: 0.45rem;
    background: #22a06b;
    border-radius: 50%;
}

.ruta {
    transition:
        transform 220ms ease,
        box-shadow 220ms ease;
}

.ruta:hover {
    transform: translateY(-6px);
    box-shadow: 0 18px 40px #14362a28;
}

@keyframes aparecer {
    from {
        opacity: 0;
        transform: translateY(18px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.ruta {
    animation: aparecer 500ms ease-out both;
}
.ruta:nth-child(2) { animation-delay: 100ms; }
.ruta:nth-child(3) { animation-delay: 200ms; }

.hero {
    color: white;
    background:
        linear-gradient(90deg, #073b2ddd, #073b2d44),
        url("../img/portada.jpg") center / cover;
}

.ruta img {
    filter: saturate(0.9) contrast(1.05);
    transition: filter 220ms ease, transform 220ms ease;
}
.ruta:hover img {
    filter: saturate(1.1) contrast(1.08);
    transform: scale(1.025);
}

@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }

    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

:root { --verde: #0a6048; --oscuro: #102820; --claro: #f2f7f4; --acento: #f7b32b; }
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; color: var(--oscuro); background: var(--claro); font-family: Arial, sans-serif; line-height: 1.6; }
img { display: block; max-width: 100%; }
a { color: inherit; }

.encabezado { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; padding: 1rem max(1rem, calc((100% - 1120px) / 2)); background: white; }
.marca { color: var(--verde); font-weight: 800; text-decoration: none; }
.menu { display: flex; flex-wrap: wrap; gap: 0.75rem 1.25rem; margin: 0; padding: 0; list-style: none; }
.menu a:focus-visible, .boton:focus-visible, .ruta a:focus-visible { outline: 3px solid var(--acento); outline-offset: 4px; }

.hero { min-height: 70vh; display: grid; align-items: center; padding: 4rem max(1rem, calc((100% - 1120px) / 2)); color: white; background: linear-gradient(90deg, #073b2dee, #073b2d44), url("../img/portada.jpg") center / cover; }
.hero__contenido { max-width: 720px; }
.hero h1 { margin: 0; font-size: clamp(2.2rem, 7vw, 5rem); line-height: 1.05; }
.boton { display: inline-block; padding: 0.75rem 1rem; color: white; background: var(--verde); border-radius: 999px; text-decoration: none; transition: background-color 180ms ease, transform 180ms ease; }
.boton:hover { background: #073b2d; transform: translateY(-2px); }

.seccion { width: min(100% - 2rem, 1120px); margin-inline: auto; padding-block: 4rem; }
.seccion__titulo { margin-bottom: 2rem; }
.rejilla-rutas { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr)); gap: 1.5rem; }
.ruta { overflow: hidden; display: flex; flex-direction: column; background: white; border-radius: 1rem; box-shadow: 0 8px 24px #14362a18; animation: aparecer 500ms ease-out both; transition: transform 220ms ease, box-shadow 220ms ease; }
.ruta:nth-child(2) { animation-delay: 100ms; }
.ruta:nth-child(3) { animation-delay: 200ms; }
.ruta:hover { transform: translateY(-6px); box-shadow: 0 18px 40px #14362a28; }
.ruta img { width: 100%; height: 220px; object-fit: cover; }
.ruta__contenido { flex: 1; display: flex; flex-direction: column; padding: 1.25rem; }
.ruta__contenido a { margin-top: auto; color: var(--verde); font-weight: 700; }
.nivel::before { content: ""; display: inline-block; width: 0.6rem; height: 0.6rem; margin-right: 0.45rem; background: #22a06b; border-radius: 50%; }
.recomendaciones { display: grid; gap: 1.5rem; }
footer { padding: 2rem; color: white; background: var(--oscuro); text-align: center; }

@keyframes aparecer {
    from { opacity: 0; transform: translateY(18px); }
    to { opacity: 1; transform: translateY(0); }
}
@media (min-width: 700px) {
    .recomendaciones { grid-template-columns: 1fr 1fr; align-items: center; }
}
@media (min-width: 1000px) {
    .ruta--principal { grid-column: span 2; }
}
@media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}
